	(375, 54, '(Laughter)', 437.070, 440.070, '''laughter'':1'),
	(376, 54, '"Must try harder."', 444.939, 446.279, '''harder'':3 ''must'':1 ''try'':2'),
	(919, 76, 'for connection.', 579.618, 580.791, '''connection'':2 ''for'':1'),
